package com.traveltourism.controller;
import com.traveltourism.model.BookingRequestDataAccess;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.security.SecureRandom;import java.sql.*;import java.util.*;
@WebServlet("/admin/bookings")
public class AdminBookingServlet extends HttpServlet{
 private static final Set<String>ST=Set.of("pending","reviewing","confirmed","completed","cancelled");
 protected void doGet(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{HttpSession s=q.getSession();if(s.getAttribute("bookingAdminCsrf")==null){byte[]b=new byte[24];new SecureRandom().nextBytes(b);s.setAttribute("bookingAdminCsrf",Base64.getUrlEncoder().withoutPadding().encodeToString(b));}Object n=s.getAttribute("bookingAdminNotice");if(n!=null){q.setAttribute("notice",n);s.removeAttribute("bookingAdminNotice");}String status=Optional.ofNullable(q.getParameter("status")).orElse("all"),search=Optional.ofNullable(q.getParameter("q")).orElse("");boolean archived="true".equals(q.getParameter("archived"));try{List<Map<String,Object>>rows=BookingRequestDataAccess.list(status,search,archived);q.setAttribute("bookings",rows);q.setAttribute("counts",BookingRequestDataAccess.counts());String ref=q.getParameter("reference");q.setAttribute("selected",ref!=null?BookingRequestDataAccess.find(ref):(rows.isEmpty()?null:rows.get(0)));}catch(SQLException e){log("Booking desk load failed",e);q.setAttribute("loadError",e.getErrorCode()==1146||e.getErrorCode()==1054?"Booking administration needs database/booking_requests_admin.sql to be run in your existing database.":"Booking requests could not be loaded.");q.setAttribute("bookings",Collections.emptyList());q.setAttribute("counts",Collections.emptyMap());}q.setAttribute("filterStatus",status);q.setAttribute("search",search);q.setAttribute("showArchived",archived);q.getRequestDispatcher("/WEB-INF/admin/bookings.jsp").forward(q,r);}
 protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException{q.setCharacterEncoding("UTF-8");HttpSession s=q.getSession(false);if(s==null||q.getParameter("csrf")==null||!q.getParameter("csrf").equals(s.getAttribute("bookingAdminCsrf"))){r.sendError(403);return;}String ref=Optional.ofNullable(q.getParameter("reference")).orElse("");if("delete".equals(q.getParameter("action"))){try{if(!BookingRequestDataAccess.deleteArchived(ref))throw new Exception();s.setAttribute("bookingAdminNotice","Archived booking request permanently deleted.");}catch(Exception e){s.setAttribute("bookingAdminNotice","Only archived booking requests can be permanently deleted.");}r.sendRedirect(q.getContextPath()+"/admin/bookings?archived=true");return;}String status=q.getParameter("status"),notes=Optional.ofNullable(q.getParameter("adminNotes")).orElse("").trim(),date=Optional.ofNullable(q.getParameter("followUpDate")).orElse("").trim(),a=q.getParameter("archiveAction");boolean archived="archive".equals(a)||(!"restore".equals(a)&&"true".equals(q.getParameter("currentArchived")));try{if(ref.isBlank()||!ST.contains(status)||notes.length()>3000)throw new IllegalArgumentException();java.sql.Date follow=date.isBlank()?null:java.sql.Date.valueOf(date);BookingRequestDataAccess.update(ref,status,notes,follow,archived);s.setAttribute("bookingAdminNotice",archived?"Booking request archived.":"Booking workflow updated.");}catch(Exception e){s.setAttribute("bookingAdminNotice","The booking update could not be saved. Check the fields and follow-up date.");}r.sendRedirect(q.getContextPath()+"/admin/bookings"+(archived?"?archived=true":"?reference="+ref));}
}